<?php
require_once __DIR__.'/../includes/bootstrap.php';
require_role('finance_officer');$user=current_user();$flashes=render_flashes();$currentPage='prepare_schedule';
$pageTitle='Prepare Stipend Schedule';require_once __DIR__.'/_helpers.php';$conn=Database::getConnection();$uid=(int)($user['id']??$user['user_id']??0);$cfg=fo_config($conn);
if($_SERVER['REQUEST_METHOD']==='POST'){fo_verify_csrf();$from=trim((string)($_POST['period_start']??''));$to=trim((string)($_POST['period_end']??''));$programme=trim((string)($_POST['programme_name']??''));$rate=(float)($_POST['daily_rate']??$cfg['default_daily_rate']);if($from===''||$to===''||strtotime($from)>strtotime($to)||$rate<0){fo_flash('danger','Valid period and rate are required.');header('Location: '.url('finance_officer/prepare_schedule.php'));exit;}$where=["faa.approval_status='approved'","faa.attendance_date BETWEEN ? AND ?"];$params=[$from,$to];$types='ss';if($programme!==''){$where[]='faa.programme_name=?';$params[]=$programme;$types.='s';}$sql="SELECT faa.participant_id,MAX(faa.programme_name) programme_name,MAX(faa.cohort_name) cohort_name,SUM(faa.approved_minutes) approved_minutes,u.first_name,u.last_name FROM finance_attendance_approved faa JOIN users u ON u.id=faa.participant_id WHERE ".implode(' AND ',$where)." GROUP BY faa.participant_id,u.first_name,u.last_name";$s=$conn->prepare($sql);$s->bind_param($types,...$params);$s->execute();$rows=[];$r=$s->get_result();while($x=$r->fetch_assoc())$rows[]=$x;$s->close();if(!$rows){fo_flash('danger','No approved attendance found for this scope.');header('Location: '.url('finance_officer/prepare_schedule.php'));exit;}$ref='STP-'.date('Ymd-His').'-'.random_int(100,999);$basis='Approved attendance minutes / 480 × daily stipend rate';$pc=count($rows);$conn->begin_transaction();try{$s=$conn->prepare("INSERT INTO stipend_schedules(schedule_reference,period_start,period_end,programme_name,daily_rate,calculation_basis,participant_count,total_amount,exception_count,status,created_by) VALUES(?,?,?,?,?,?,?,0,0,'draft',?)");$s->bind_param('ssssdsii',$ref,$from,$to,$programme,$rate,$basis,$pc,$uid);$s->execute();$sid=$s->insert_id;$s->close();$total=0;$exc=0;$ins=$conn->prepare("INSERT INTO stipend_schedule_lines(schedule_id,participant_id,participant_name_snapshot,programme_name_snapshot,cohort_name_snapshot,approved_minutes,eligible_days,daily_rate,gross_amount,exception_code,exception_message) VALUES(?,?,?,?,?,?,?,?,?,?,?)");foreach($rows as $x){$c=fo_calc((int)$x['approved_minutes'],$rate,(int)$cfg['minimum_attendance_minutes']);$pn=trim($x['first_name'].' '.$x['last_name']);$code=$c['exception']?'ATTENDANCE_EXCEPTION':null;$msg=$c['exception'];if($msg)$exc++;$mins=(int)$x['approved_minutes'];$days=(float)$c['days'];$gross=(float)$c['gross'];$prog=(string)$x['programme_name'];$cohort=(string)$x['cohort_name'];$ins->bind_param('iisssidddss',$sid,$x['participant_id'],$pn,$prog,$cohort,$mins,$days,$rate,$gross,$code,$msg);$ins->execute();$total+=$gross;}$ins->close();$u=$conn->prepare("UPDATE stipend_schedules SET total_amount=?,exception_count=? WHERE id=?");$u->bind_param('dii',$total,$exc,$sid);$u->execute();$u->close();$conn->commit();fo_activity($conn,$uid,'stipend_schedule_created','Prepared stipend schedule from approved attendance.','stipend_schedule',$sid);fo_flash('success','Stipend schedule prepared successfully.');header('Location: '.url('finance_officer/schedule_view.php?id='.$sid));exit;}catch(Throwable $e){$conn->rollback();fo_flash('danger','Schedule preparation failed.');header('Location: '.url('finance_officer/prepare_schedule.php'));exit;}}
$programmes=[];if(fo_has_table($conn,'finance_attendance_approved')){$r=$conn->query("SELECT DISTINCT programme_name FROM finance_attendance_approved WHERE approval_status='approved' AND programme_name<>'' ORDER BY programme_name");if($r)while($x=$r->fetch_assoc())$programmes[]=$x['programme_name'];}require __DIR__.'/_layout_start.php';?>
<div class="fo-page-header"><div><span>Schedule Builder</span><h2>Prepare Stipend Schedule</h2><p>Generate a draft from approved attendance.</p></div></div><div class="fo-grid"><section class="fo-card"><div class="fo-card__header"><h3>Schedule Scope</h3></div><form method="post" class="fo-form"><input type="hidden" name="csrf_token" value="<?= e(fo_csrf_token()) ?>"><label>Period Start<input type="date" name="period_start" required></label><label>Period End<input type="date" name="period_end" required></label><label>Programme<select name="programme_name"><option value="">All programmes</option><?php foreach($programmes as $p):?><option value="<?= e($p) ?>"><?= e($p) ?></option><?php endforeach;?></select></label><label>Daily Stipend Rate<input type="number" min="0" step="0.01" name="daily_rate" value="<?= e((string)$cfg['default_daily_rate']) ?>" required></label><button class="fo-btn fo-btn--primary"><i class="fas fa-calculator"></i> Generate Draft Schedule</button></form></section><section class="fo-card"><div class="fo-card__header"><h3>Calculation Basis</h3></div><div class="fo-principles"><div><i class="fas fa-calculator"></i><strong>Formula</strong><span>Approved minutes ÷ 480 × daily rate.</span></div><div><i class="fas fa-triangle-exclamation"></i><strong>Exceptions stay visible</strong><span>Low attendance is flagged, not hidden.</span></div><div><i class="fas fa-user-shield"></i><strong>Maker / checker</strong><span>Maker cannot final-approve when segregation is enabled.</span></div></div></section></div>
<?php require __DIR__.'/_layout_end.php';?>